const email = String($json.email || '')
  .trim()
  .toLowerCase();

return {
  json: {
    ...$json,
    normalizedEmail: email,
    submitted_at: new Date().toISOString()
  }
};

const original = $('Prepare Lead Data').first().json;

// Preserve the safety result from the incoming lead.
const safetyFlag =
  $('Safety Check').first().json.safety_flag === true;

const normalizeEmail = value =>
  String(value || '')
    .trim()
    .toLowerCase();

const normalizePhone = value =>
  String(value || '')
    .replace(/\D/g, '');

const incomingEmail = normalizeEmail(
  original.normalizedEmail || original.email
);

const incomingPhone = normalizePhone(original.phone);

const incomingSubmissionId = String(
  original.submission_id || ''
).trim();

const incomingTime = new Date(original.submitted_at).getTime();
const twelveHours = 12 * 60 * 60 * 1000;

const rows = $input.all();

const duplicate = rows.some(item => {
  const row = item.json;

  const rowSubmissionId = String(
    row.submission_id || ''
  ).trim();

  // 1. Identical submission ID means the same submission.
  if (
    incomingSubmissionId &&
    rowSubmissionId &&
    rowSubmissionId === incomingSubmissionId
  ) {
    return true;
  }

  // Everything below requires a valid timestamp.
  const submittedAt = row.submitted_at;

  if (!submittedAt) {
    return false;
  }

  const rowTime = new Date(submittedAt).getTime();

  if (
    Number.isNaN(rowTime) ||
    Number.isNaN(incomingTime)
  ) {
    return false;
  }

  // Only consider leads within the 12-hour window.
  const timeDifference = Math.abs(incomingTime - rowTime);

  if (timeDifference > twelveHours) {
    return false;
  }

  const rowEmail = normalizeEmail(row.email);
  const rowPhone = normalizePhone(row.phone);

  // 2. Prefer email + phone when both are available.
  if (
    incomingEmail &&
    incomingPhone &&
    rowEmail === incomingEmail &&
    rowPhone === incomingPhone
  ) {
    return true;
  }

  // 3. If incoming phone is missing, use email.
  if (
    incomingEmail &&
    !incomingPhone &&
    rowEmail === incomingEmail
  ) {
    return true;
  }

  // 4. If incoming email is missing, use phone.
  if (
    !incomingEmail &&
    incomingPhone &&
    rowPhone === incomingPhone
  ) {
    return true;
  }

  return false;
});

return [
  {
    json: {
      ...original,
      duplicate,
      safety_flag: safetyFlag
    }
  }
];

const result = $json.output?.[0]?.content?.[0]?.text;

if (!result || typeof result !== "object") {
  throw new Error("AI returned no valid classification object");
}

const validLeadTypes = ["hot", "warm", "cold"];

if (!validLeadTypes.includes(result.lead_type)) {
  throw new Error(
    `Invalid lead_type returned by AI: "${result.lead_type}". Expected hot, warm, or cold.`
  );
}

if (!result.service) {
  throw new Error("AI classification is missing service");
}

const validUrgencies = ["urgent", "soon", "non_urgent"];

if (!validUrgencies.includes(result.urgency)) {
  throw new Error("AI returned an invalid urgency");
}

if (typeof result.needs_human_review !== "boolean") {
  throw new Error("AI returned an invalid human-review flag");
}

// Retrieve the original lead after duplicate checking.
const original = $('Normalise Lead data').first().json;

const safetyFlag = original.safety_flag === true;

// Safety concerns must always receive human review.
const needsHumanReview =
  safetyFlag || result.needs_human_review;

// Safety concerns override ordinary lead classification.
const leadType = safetyFlag ? "hot" : result.lead_type;
const urgency = safetyFlag ? "urgent" : result.urgency;

const priorityMap = {
  hot: "high",
  warm: "normal",
  cold: "low"
};

const reviewReason = safetyFlag
  ? "Potential HVAC safety hazard. Immediate human review required."
  : result.review_reason || "";

return {
  json: {
    ...original,

    lead_type: leadType,
    service: result.service,
    urgency,
    reason: result.summary || "No summary provided",
    priority: priorityMap[leadType],

    safety_flag: safetyFlag,
    needs_human_review: needsHumanReview,
    review_reason: reviewReason
  }
};

const response = `Hi ${$json.name},

Thanks for reaching out about ${$json.service}. We’ve received your inquiry and will get back to you shortly.

Best regards,
${$('Client Config').item.json.business_name}`;

return {
  json: {
    ...$json,
    response: response
  }
};

const missingFields = [];

const isEmpty = value =>
  value === undefined ||
  value === null ||
  String(value).trim() === "";

if (isEmpty($json.name)) {
  missingFields.push("name");
}

if (isEmpty($json.email)) {
  missingFields.push("email");
}

const hasMessage = !isEmpty($json.message);
const hasService = !isEmpty($json.service);

if (!hasMessage && !hasService) {
  missingFields.push("message_or_service");
}

return {
  json: {
    ...$json,
    valid: missingFields.length === 0,
    missingFields
  }
};

const items = $input.all();

return items.map(item => {
  const original = item.json;

  const message = String(original.message ?? "")
    .toLowerCase()
    .replace(/[’‘]/g, "'")
    .replace(/\s+/g, " ")
    .trim();

  // Split at sentence boundaries and contrast words.
  // This helps distinguish:
  // "No smoke, but I smell gas."
  // from:
  // "There are no unusual smells, smoke, or electrical issues."
  const clauses = message
    .split(/[.!?;]|\b(?:but|however|although)\b/g)
    .map(s => s.trim())
    .filter(Boolean);

  const hazardDefinitions = [
    {
      name: "gas",
      positive: [
        /\b(?:smell|smells|smelling|odor|odour|scent)\b.{0,50}\bgas\b/,
        /\bgas\b.{0,50}\b(?:smell|smells|smelling|odor|odour|scent)\b/,
        /\bgas (?:leak|leaking|escaping)\b/,
        /\b(?:leaking|leak)\b.{0,35}\bgas\b/,
        /\brotten eggs?\b/
      ],
      terms: [
        /\bgas\b/,
        /\brotten eggs?\b/
      ]
    },
    {
      name: "smoke_or_fire",
      positive: [
        /\bsmoke\b/,
        /\bsmoking\b/,
        /\bflames?\b/,
        /\b(?:on fire|caught fire|electrical fire)\b/,
        /\bburning (?:smell|odor|odour|wires?|plastic)\b/
      ],
      terms: [
        /\bsmoke\b/,
        /\bsmoking\b/,
        /\bflames?\b/,
        /\bfire\b/,
        /\bburning (?:smell|odor|odour)\b/
      ]
    },
    {
      name: "electrical",
      positive: [
        /\bsparks?\b/,
        /\bsparking\b/,
        /\belectrical (?:fire|burning|smell|smoke|hazard|issues?)\b/,
        /\b(?:exposed|burning) wires?\b/
      ],
      terms: [
        /\bsparks?\b/,
        /\bsparking\b/,
        /\belectrical\b/,
        /\b(?:exposed|burning) wires?\b/
      ]
    },
    {
      name: "carbon_monoxide",
      positive: [
        /\bcarbon monoxide\b/,
        /\bco (?:detector|alarm)\b/
      ],
      terms: [
        /\bcarbon monoxide\b/,
        /\bco (?:detector|alarm)\b/
      ]
    }
  ];

  // Explicit denial at the start of a clause.
  const denialStart =
    /\b(?:no|without|none of|not experiencing|not seeing|not smelling|don't have|do not have|haven't noticed|have not noticed|there (?:is|are) no)\b/;

  // Identify whether a hazard term falls within an explicit
  // denial. Covers lists such as:
  // "no unusual smells, smoke, or electrical issues".
  function getDeniedText(clause) {
    const match = denialStart.exec(clause);

    if (!match) return "";

    const afterDenial = clause.slice(
      match.index + match[0].length
    );

    // A denial must not extend into a new positive report.
    return afterDenial.split(
      /\b(?:but|however|although|except|yet)\b/
    )[0];
  }

  function evaluateHazard(hazard) {
    let detected = false;
    let denied = false;

    for (const clause of clauses) {
      const deniedText = getDeniedText(clause);

      const hazardDenied = deniedText &&
        hazard.terms.some(pattern =>
          pattern.test(deniedText)
        );

      if (hazardDenied) {
        denied = true;
      }

      // Remove explicitly denied text before looking for
      // positive hazard reports in the same clause.
      let positiveText = clause;

      if (deniedText) {
        const denialMatch = denialStart.exec(clause);

        positiveText = clause.slice(
          0,
          denialMatch.index
        );

        // Retain any text after a contrast expression.
        const contrast = clause.match(
          /\b(?:but|however|although|except|yet)\b/
        );

        if (contrast) {
          positiveText += " " + clause.slice(
            contrast.index + contrast[0].length
          );
        }
      }

      if (
        hazard.positive.some(pattern =>
          pattern.test(positiveText)
        )
      ) {
        detected = true;
      }
    }

    return {
      hazard: hazard.name,
      detected,
      denied
    };
  }

  const findings = hazardDefinitions.map(
    evaluateHazard
  );

  const detectedHazards = findings
    .filter(finding => finding.detected)
    .map(finding => finding.hazard);

  // Unusual or unidentified smells should receive human
  // review even without a confirmed hazard.
  const ambiguousPatterns = [
    /\b(?:strange|weird|funny|unusual|odd|unknown)\b.{0,35}\b(?:smell|smells|odor|odour)\b/,
    /\b(?:smell|smells|odor|odour)\b.{0,35}\b(?:strange|weird|funny|unusual|odd)\b/,
    /\b(?:smell|smells|odor|odour)\b.{0,35}\b(?:not sure|unsure|can't tell)\b/
  ];

  const ambiguous = clauses.some(clause => {
    const deniedText = getDeniedText(clause);

    let textToCheck = clause;

    if (deniedText) {
      const denialMatch = denialStart.exec(clause);

      textToCheck = clause.slice(
        0,
        denialMatch.index
      );
    }

    return ambiguousPatterns.some(pattern =>
      pattern.test(textToCheck)
    );
  });

  // If the customer reports a possible hazard using
  // uncertain language, send it for review.
  const uncertaintyPatterns = [
    /\b(?:maybe|possibly|might be|could be|not sure if|unsure if)\b.{0,60}\b(?:gas|smoke|fire|sparks?|carbon monoxide|burning)\b/,
    /\b(?:gas|smoke|fire|sparks?|carbon monoxide|burning)\b.{0,60}\b(?:maybe|possibly|not sure|unsure)\b/
  ];

  const uncertainHazard = clauses.some(clause =>
    uncertaintyPatterns.some(pattern =>
      pattern.test(clause)
    )
  );

  const safetyFlag = detectedHazards.length > 0;

  const needsHumanReview =
    safetyFlag ||
    ambiguous ||
    uncertainHazard;

  let reviewReason = "";

  if (safetyFlag) {
    reviewReason =
      `Potential safety hazard: ${detectedHazards.join(", ")}. Immediate human review required.`;
  } else if (uncertainHazard) {
    reviewReason =
      "Customer describes a possible safety hazard with uncertainty. Human review required.";
  } else if (ambiguous) {
    reviewReason =
      "Unclear odor or possible safety concern. Human review required.";
  }

  return {
    json: {
      ...original,
      safety_flag: safetyFlag,
      needs_human_review: needsHumanReview,
      review_reason: reviewReason,
      detected_hazards: detectedHazards,
      safety_findings: findings
    }
  };
});
